class Solution {
    public int[] sortedSquares(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];

        int left = 0, right = n - 1;
        int pos = n - 1; // Fill from the end (largest squares)

        while (left <= right) {
            int leftSq = nums[left] * nums[left];
            int rightSq = nums[right] * nums[right];

            if (leftSq > rightSq) {
                result[pos] = leftSq;
                left++;
            } else {
                result[pos] = rightSq;
                right--;
            }
            pos--;
        }

        return result;
    }
}

import java.util.Arrays;

class Solution {
    public int[] sortedSquares(int[] nums) {
        int[] result = new int[nums.length];

        for (int i = 0; i < nums.length; i++) {
            result[i] = nums[i] * nums[i];
        }

        Arrays.sort(result);
        return result;
    }
}

class Solution {
    public int[] sortedSquares(int[] nums) {
        int n = nums.length;

        // Find first non-negative index
        int split = 0;
        while (split < n && nums[split] < 0) {
            split++;
        }

        int[] result = new int[n];
        int left = split - 1; // Negative numbers (go left)
        int right = split;     // Non-negative numbers (go right)
        int pos = 0;

        // Merge two halves
        while (left >= 0 && right < n) {
            int leftSq = nums[left] * nums[left];
            int rightSq = nums[right] * nums[right];

            if (leftSq < rightSq) {
                result[pos++] = leftSq;
                left--;
            } else {
                result[pos++] = rightSq;
                right++;
            }
        }

        // Remaining negative squares
        while (left >= 0) {
            result[pos++] = nums[left] * nums[left];
            left--;
        }

        // Remaining positive squares
        while (right < n) {
            result[pos++] = nums[right] * nums[right];
            right++;
        }

        return result;
    }
}
